1	package org.springframework.samples.petclinic.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.http.HttpStatus;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.web.bind.annotation.ResponseStatus;
10	
11	/**
12	 * Business rule: every owner is identified by a single derived {@code identityKey} of
13	 * {@code normalizedTelephone|email|householdId}. This consolidates the former separate
14	 * telephone, email and household duplicate checks into one key: on creation an owner is
15	 * rejected only when its WHOLE identityKey exactly matches an existing owner's. Because the
16	 * telephone is part of the key, two members of the same household (same householdId) with
17	 * different telephones have different identityKeys and are both allowed; only an exact
18	 * full-key match is a duplicate. Kept as a small, self-contained unit so the rule can be
19	 * enforced from the create flow without adding complexity to the controller or service.
20	 */
21	public final class OwnerIdentityPolicy {
22	
23	    private OwnerIdentityPolicy() {
24	    }
25	
26	    /**
27	     * Assign the owner's householdId (when it knowingly joins an existing household) and reject
28	     * the owner when its whole identityKey matches any other existing owner's.
29	     *
30	     * @param clinicService   source of the existing owners
31	     * @param owner           the owner being created
32	     * @param sharesHousehold whether the request opted in to a shared household
